WITH StudentList AS (
  SELECT student_id, full_name FROM Students
),
CourseTotals AS (
  SELECT student_id, COUNT(*) AS courses_enrolled FROM Courses GROUP BY student_id
)
SELECT s.full_name, c.courses_enrolled
FROM StudentList s
JOIN CourseTotals c ON s.student_id = c.student_id;

